function validate([num]) {
  if (typeof num !== 'string') return 'num must be a string of digits.';
  if (num.length < 1 || num.length > 35) return 'num needs 1 to 35 digits.';
  if (!/^[0-9]+$/.test(num)) return 'num may contain only the digits 0-9.';
  return null;
}

