function isAdditiveNumber(num) {
  const n = num.length;
  const addStrings = (a, b) => {
    let i = a.length - 1;
    let j = b.length - 1;
    let carry = 0;
    let result = '';
    while (i >= 0 || j >= 0 || carry > 0) {
      const digit = (i >= 0 ? +a[i--] : 0) + (j >= 0 ? +b[j--] : 0) + carry;
      result = (digit % 10) + result;
      carry = Math.floor(digit / 10);
    }
    return result;
  };

  for (let firstLen = 1; firstLen <= n - 2; firstLen++) {
    if (firstLen > 1 && num[0] === '0') break;
    for (let secondLen = 1; firstLen + secondLen < n; secondLen++) {
      if (secondLen > 1 && num[firstLen] === '0') break;
      let first = num.slice(0, firstLen);
      let second = num.slice(firstLen, firstLen + secondLen);
      let start = firstLen + secondLen;
      while (start < n) {
        const sum = addStrings(first, second);
        if (!num.startsWith(sum, start)) break;
        start += sum.length;
        first = second;
        second = sum;
      }
      if (start === n) return true;
    }
  }
  return false;
}

