function isAdditiveNumber(num) {
  const parts = [];
  const dfs = (pos) => {
    if (pos === num.length) return parts.length >= 3;
    for (let end = pos + 1; end <= num.length; end++) {
      const piece = num.slice(pos, end);
      if (piece.length > 1 && piece[0] === '0') break;
      const value = BigInt(piece);
      const k = parts.length;
      if (k >= 2 && parts[k - 1] + parts[k - 2] !== value) continue;
      parts.push(value);
      if (dfs(end)) return true;
      parts.pop();
    }
    return false;
  };
  return dfs(0);
}

