function generate(rand, size) {
  const maxLen = size === 'large' ? 35 : 12;
  const pick = (k) => Math.floor(rand() * k);
  const randomNumber = (maxDigits) => {
    if (rand() < 0.15) return '0';
    let s = String(1 + pick(9));
    const len = 1 + pick(maxDigits);
    while (s.length < len) s += pick(10);
    return s;
  };
  if (rand() < 0.2) {
    const len = 1 + pick(maxLen);
    let s = '';
    while (s.length < len) s += rand() < 0.3 ? '0' : String(pick(10));
    return [s];
  }
  for (;;) {
    const digits = size === 'large' ? 1 + pick(10) : 1 + pick(2);
    let a = BigInt(randomNumber(digits));
    let b = BigInt(randomNumber(digits));
    let s = String(a) + String(b);
    let count = 2;
    while (s.length + String(a + b).length <= maxLen) {
      const c = a + b;
      s += String(c);
      a = b;
      b = c;
      count++;
      if (size !== 'large' && rand() < 0.3) break;
    }
    if (count < 3) continue;
    const roll = rand();
    if (roll < 0.25) {
      const at = pick(s.length);
      s = s.slice(0, at) + String((+s[at] + 1 + pick(9)) % 10) + s.slice(at + 1);
    } else if (roll < 0.35 && s.length < maxLen) {
      s += String(pick(10));
    } else if (roll < 0.45 && s.length > 1) {
      s = s.slice(0, -1);
    }
    return [s];
  }
}
